statement:
One table logs product purchases:

- `user_transactions(transaction_id, product_id, spend, transaction_date)`: one row per purchase; `transaction_id` is unique, `spend` is a positive amount with two decimals and `transaction_date` is a datetime such as `'2020-12-31 12:00:00'`.
- For every product, the calendar years in which it has purchases are consecutive (no gap years), so a product's previous year with data is always the calendar year just before.

For each product and each calendar year in which it was bought, report:

- `year`: the calendar year of the purchases;
- `product_id`;
- `curr_year_spend`: the product's total `spend` in that year;
- `prev_year_spend`: the product's total `spend` in the year before, or `null` for the product's first year;
- `yoy_rate`: the growth as a percentage, `(curr_year_spend - prev_year_spend) / prev_year_spend * 100`, rounded to 2 decimals, or `null` when there is no previous year.

Order the rows by `product_id` ascending, then by `year` ascending.

validator:
function validate(input) {
  const [{ user_transactions = [] }] = input;
  const ids = new Set(), years = new Map();
  for (const [id, product, spend, when] of user_transactions) {
    if (id === null || product === null || spend === null || when === null) return 'No value in user_transactions may be null.';
    if (ids.has(id)) return `transaction_id ${id} appears twice.`;
    ids.add(id);
    if (!(spend > 0) || Math.abs(spend * 100 - Math.round(spend * 100)) > 1e-6) return `spend ${spend} must be positive with at most two decimals.`;
    if (!/^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/.test(when)) return `transaction_date ${when} must look like 2020-12-31 12:00:00.`;
    if (!years.has(product)) years.set(product, new Set());
    years.get(product).add(Number(when.slice(0, 4)));
  }
  for (const [product, set] of years) {
    const list = [...set];
    if (Math.max(...list) - Math.min(...list) + 1 !== list.length) return `Product ${product} skips a year between its purchases.`;
  }
  return null;
}

generator:
function generate(rand, size) {
  const pick = list => list[Math.floor(rand() * list.length)];
  const pad = n => String(n).padStart(2, '0');
  const small = size === 'small';
  const target = small ? Math.floor(rand() * 9) : 2000;
  const productPool = small ? [7, 12, 123424] : Array.from({ length: 150 }, (_, i) => 1000 + i * 7);
  const spendPool = [100, 150, 200, 50, 1500.6, 1000.2, 1246.44, 99.99, 0.5, 2145.32];
  const spend = () => small && rand() < 0.7 ? pick(spendPool) : Math.round(1 + rand() * 300000) / 100;
  const stamp = year => `${year}-${pad(1 + Math.floor(rand() * 12))}-${pad(1 + Math.floor(rand() * 28))} ${pad(Math.floor(rand() * 24))}:${pad(Math.floor(rand() * 60))}:00`;
  // Every product gets one purchase in each year of its span first, so its years stay consecutive.
  const spans = [], rows = [];
  for (const product of productPool) {
    if (rows.length >= target) break;
    const start = (small ? 2019 : 2015) + Math.floor(rand() * 4), length = Math.min(1 + Math.floor(rand() * (small ? 3 : 6)), target - rows.length);
    if (small && rand() < 0.3) continue;
    spans.push([product, start, length]);
    for (let year = start; year < start + length; year++) rows.push([product, spend(), stamp(year)]);
  }
  while (spans.length && rows.length < target) {
    const [product, start, length] = pick(spans);
    rows.push([product, spend(), stamp(start + Math.floor(rand() * length))]);
  }
  for (let i = rows.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [rows[i], rows[j]] = [rows[j], rows[i]]; }
  const base = small ? 1 : 1300;
  return [{ user_transactions: rows.map(([product, amount, when], i) => [base + i * (small ? 1 : 3), product, amount, when]) }];
}
